urlset:
{%- for entry in entries %}

        {{ entry.permalink | escape_xml | safe }}
        {%- if entry.updated %}
        {{ entry.updated }}
        {%- endif %}
        {%- if entry.extra is defined and entry.extra.preview_image %}
        {%- set img = entry.extra.preview_image %}
        {#- Same resolution as base.html: a bare filename is one of the page's
            own colocated assets, which Zola copies into the page's own output
            directory, so it hangs off the permalink rather than the site root. -#}
        {%- if img is starting_with(pat='http') %}
        {%- set img_loc = img -%}
        {%- elif img is containing(pat='/') %}
        {%- set img_loc = config.base_url ~ '/' ~ (img | trim_start(pat='/')) -%}
        {%- else %}
        {%- set img_loc = entry.permalink ~ (img | urlencode) -%}
        {%- endif %}

            {{ img_loc | escape_xml | safe }}

        {%- endif %}

{%- endfor %}
